INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李存孝", "aliases": ["安敬思"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李存孝，在此段中为李克用养子。", "biography": null, "status": "draft", "id": "d25efb4e-74a3-5bab-b1e4-a79cee0716c3"}, {"name": "李存信", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李存信，在此段中为李克用养子。", "biography": null, "status": "draft", "id": "31ad8087-ed47-5400-bf8a-47f2edb81920"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "王镕", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加授王镕、罗绍威、王处直官衔”中为受授者。", "biography": null, "status": "draft", "id": "a3d42aab-7a1f-51f4-84bc-35192b430637"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "时溥", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的时溥：求援者。", "biography": null, "status": "draft", "id": "075f8bab-c2fc-5a9e-b8b2-a0d12c7ac981"}, {"name": "张璲", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：张璲。", "biography": null, "status": "draft", "id": "12199d51-f037-569f-9611-6b6f18f6b14c"}, {"name": "张谏", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：张谏。", "biography": null, "status": "draft", "id": "85b37b8d-194c-5e3d-95b4-f53ba9042b2b"}, {"name": "朱友裕", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：朱友裕。", "biography": null, "status": "draft", "id": "fd61394b-01c5-5bba-9d50-af1029c306bc"}, {"name": "邵伦", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：邵伦。", "biography": null, "status": "draft", "id": "41173559-3889-5012-9b93-32b697e8de38"}, {"name": "王坛（孙儒将）", "aliases": ["王坛"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：王坛（孙儒将）。", "biography": null, "status": "draft", "id": "20dd318a-0941-55cf-822d-b15758c49b74"}, {"name": "蒋环", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的蒋环：邀兵并共同进攻。", "biography": null, "status": "draft", "id": "4f14242e-83af-5e65-b821-2de1b89870a4"}, {"name": "孙儒", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：孙儒。", "biography": null, "status": "draft", "id": "4426793f-0bd8-5a79-919f-7e3a0ddae520"}, {"name": "蔡俦", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：蔡俦。", "biography": null, "status": "draft", "id": "259ff539-524f-5563-968a-93bf4928f8e2"}, {"name": "杨行密", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：杨行密。", "biography": null, "status": "draft", "id": "ad75628e-5958-5672-9403-eb349ca77e6e"}, {"name": "倪章", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：倪章。", "biography": null, "status": "draft", "id": "17ffe118-5a6f-5f8e-9769-73bc7f01ffce"}, {"name": "李神福", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李神福，在此段中为用疑兵解围者。", "biography": null, "status": "draft", "id": "61a41119-a9f8-5beb-8356-77ed00b4ae34"}, {"name": "边冈", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description":