ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李存孝欲取镇冀立功，李存信从中阻挠", "start_year": null, "end_year": null, "time_original": "初；具体年月未载", "dynasty": "唐", "description": "《通鉴》追述李存孝与李存信俱为李克用假子，不相睦。李存信受李克用宠信；李存孝在邢州想立功超过李存信，建议取镇冀，李存信从中阻挠，使建议未及时获准。", "phases": [], "location_name": "邢州、镇州、冀州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0909d303-c645-56de-8e03-82e86468fd23"}, {"title": "李存孝救尧山不克，二将猜忌迟兵", "start_year": null, "end_year": null, "time_original": "及王镕围尧山；具体日未载", "dynasty": "唐", "description": "王镕围尧山时，李存孝救援未成功。李克用以李存信为蕃、马步都指挥使，与李存孝共同出击；二人互相猜忌，迟滞不进。", "phases": [], "location_name": "尧山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c21cea3c-8649-58e5-aac6-497576e26f1a"}, {"title": "李嗣勋尧山击败幽镇联军", "start_year": 892, "end_year": 892, "time_original": "892年正月条；具体日未载", "dynasty": "唐", "description": "王镕、李匡威合兵十余万攻尧山，李克用遣李嗣勋迎击，大破幽州镇州军，书载斩获三万。", "phases": [], "location_name": "尧山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "52e239b7-3bf4-548a-a819-70cb7ce42cd4"}, {"title": "李存信指控李存孝无心击敌、有私约", "start_year": null, "end_year": null, "time_original": "尧山战后；具体日未载", "dynasty": "唐", "description": "李存信返回后向李克用谮言李存孝无心击敌，并怀疑他与敌方有私约。李存孝闻后认为自己有功而信任不及李存信，愤怨且怕遭祸。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "296cfa4e-7a60-5f44-81be-9cda1daf45d4"}, {"title": "李存孝结王镕朱全忠、上表求脱离河东", "start_year": 892, "end_year": 892, "time_original": "892年冬十月条所附；具体日未载", "dynasty": "唐", "description": "李存孝秘密联结王镕及朱全忠，上表请求邢洺磁三州直接归朝廷，请赐旌节并会诸道兵讨李克用。朝廷授其邢洺磁节度使，但不许会兵。", "phases": [], "location_name": "邢州、洺州、磁州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "aa2dd5bf-ac5b-505a-9817-0e14cedf838d"}, {"title": "张璲张谏以濠泗二州附朱全忠", "start_year": 892, "end_year": 892, "time_original": "892年十一月", "dynasty": "唐", "description": "时溥所属濠州刺史张璲、泗州刺史张谏，各以其州归附朱全忠。", "phases": [], "location_name": "濠州、泗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "16fbe746-bb92-5900-8c6d-05bb6bf69de0"}, {"title": "朱友裕率十万取濮州、执邵伦", "start_year": 892, "end_year": 892, "time_original": "892年十一月乙未", "dynasty": "唐", "description": "朱全忠派其子朱友裕率十万兵攻濮州，攻下城并捕获刺史邵伦。", "phases": [], "location_name": "濮州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "145f4f36-fb7a-5461-b0b5-ab620cca77f8"}, {"title": "朱全忠令朱友裕移兵击时溥", "start_year": 892, "end_year": 892, "time_original": "濮州被拔后；具体日未载", "dynasty": "唐", "description": "朱全忠随即命朱友裕移兵攻时溥。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "c86d9a96-53eb-57a4-90a4-8056c6daf7fa"}, {"title": "孙儒将王坛陷婺州，蒋环出奔", "start_year": 892, "end_year": 892, "time_original": "892年十一月条所附；具体日未载", "dynasty": "唐", "description": "底本称孙儒将王坛攻陷婺州，刺史蒋环逃奔赵州。", "phases": [], "location_name": "婺州、赵州（底本，待考）", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5491ee0a-b8c5-55f2-9b92-ca519f8138e5"}, {"title": "蔡俦发杨氏祖父墓、联倪章求朱援", "start_year": 892, "end_year": 892, "time_original": "892年十一月条所附；具体日未载", "dynasty": "唐", "description": "庐州刺史蔡俦挖杨行密祖父墓，与舒州刺史倪章连兵，派使者向朱全忠送印求援。", "phases": [], "location_name": "庐州、舒州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bb69cfcd-461f-5bf5-94fe-7ab1ba7670f6"}, {"title": "朱全忠收蔡俦印不救、告杨行密", "start_year": 892, "end_year": 892, "time_original": "蔡俦求援后；具体日未载", "dynasty": "唐", "description": "朱全忠嫌恶蔡俦反复，接受其印却不援救，并通牒告知杨行密，杨行密向朱全忠致谢。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "c558a93c-e1c5-57a2-a997-d2fb3d933d2f"}, {"title": "杨行密遣李神福讨蔡俦", "start_year": 892, "end_year": 892, "time_original": "获朱全忠通报后；具体日未载", "dynasty": "唐", "description": "杨行密派行营都指挥使李神福率兵讨蔡俦。", "phases": [], "location_name": "庐州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7cefb978-3127-5823-8e93-f67e2ce94c3c"}, {"title": "边冈献新历，定名景福崇玄历", "start_year": 892, "end_year": 892, "time_original": "892年十二月", "dynasty": "唐", "description": "《宣明历》渐有偏差，太子少詹事边冈编成新历，十二月上献，命名《景福崇玄历》。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "d606631f-5471-5b55-a2d3-c671238e7b93"}, {"title": "华洪阆州击败杨守亮", "start_year": 892, "end_year": 892, "time_original": "892年十二月壬午", "dynasty": "唐", "description": "王建派华洪在阆州攻杨守亮，击败之。", "phases": [], "location_name": "阆州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "06ffda66-4325-5c03-bee8-95da2c096e9c"}, {"title": "郑顼使朱全忠，论剑阁之险", "start_year": 892, "end_year": 892, "time_original": "892年十二月条；具体日未载", "dynasty": "唐", "description": "王建派节度押牙郑顼出使朱全忠。朱全忠问剑阁，郑顼力言险峻；朱不信，郑称若不告知怕误其军机，朱大笑。", "phases": [], "location_name": "剑阁（谈论对象）", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cba2e0be-46a4-5db1-8feb-d06262d6c92f"}, {"title": "钟文季卒，黄晟自称明州刺史", "start_year": 892, "end_year": 892, "time_original": "是岁；892年，具体月日未载", "dynasty": "唐", "description": "明州刺史钟文季去世，其将黄晟自称刺史。", "phases": [], "location_name": "明州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "dcba0a44-5013-52b0-bd68-478e0fc9ac22"}]'::jsonb)
