INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "《通鉴》追述李存孝与李存信俱为李克用假子，不相睦。李存信受李克用宠信；李存孝在邢州想立功超过李存信，建议取镇冀，李存信从中阻挠，使建议未及时获准。", "citation": "卷259·景福元年（892）·zztj-v259-y0892-p039·原文件第44行", "note": "原文：初，邢、洺、磁州留后李存孝，与李存信俱为李克用假子，不相睦。存信有宠于克用，存孝在邢州，欲立大功以胜之，乃建议取镇冀；存信从中沮之，不时听许。及王镕围尧山，存孝救之，不克。克用以存信为蕃、马步都指挥使，与存孝共击之，二人互相猜忌，逗留不进；克用更遣李嗣勋等击破之。存信还，谮存孝无心击贼，疑与之有私约。存孝闻之，自以有功于克用，而信任顾不及存信，愤怨，且惧及祸，乃潜结王镕及硃全忠，上表以三州自归于朝廷，乞赐旌节及会诸道兵讨李克用；诏以存孝为邢、洺、磁节度使，不许会兵。；核对说明：初追叙，年空；宠信、意图及不睦归于史书叙述，不据同时任将推盟友。", "status": "draft", "id": "d2c7949e-aaa6-515c-9826-10b456eb2942", "subject_id": "0909d303-c645-56de-8e03-82e86468fd23", "source_id": "0d7e3338-8a81-52c8-ab61-c2938c1c8382"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "初；具体年月未载", "citation": "卷259·景福元年（892）·zztj-v259-y0892-p039·原文件第44行", "note": "原文：初，邢、洺、磁州留后李存孝，与李存信俱为李克用假子，不相睦。存信有宠于克用，存孝在邢州，欲立大功以胜之，乃建议取镇冀；存信从中沮之，不时听许。及王镕围尧山，存孝救之，不克。克用以存信为蕃、马步都指挥使，与存孝共击之，二人互相猜忌，逗留不进；克用更遣李嗣勋等击破之。存信还，谮存孝无心击贼，疑与之有私约。存孝闻之，自以有功于克用，而信任顾不及存信，愤怨，且惧及祸，乃潜结王镕及硃全忠，上表以三州自归于朝廷，乞赐旌节及会诸道兵讨李克用；诏以存孝为邢、洺、磁节度使，不许会兵。；核对说明：初追叙，年空；宠信、意图及不睦归于史书叙述，不据同时任将推盟友。", "status": "draft", "id": "360cb5cf-3c76-5557-aeb5-3ce2e6155eb3", "subject_id": "0909d303-c645-56de-8e03-82e86468fd23", "source_id": "0d7e3338-8a81-52c8-ab61-c2938c1c8382"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李存孝：建议取镇冀者。", "citation": "卷259·景福元年（892）·zztj-v259-y0892-p039·原文件第44行", "note": "原文：初，邢、洺、磁州留后李存孝，与李存信俱为李克用假子，不相睦。存信有宠于克用，存孝在邢州，欲立大功以胜之，乃建议取镇冀；存信从中沮之，不时听许。及王镕围尧山，存孝救之，不克。克用以存信为蕃、马步都指挥使，与存孝共击之，二人互相猜忌，逗留不进；克用更遣李嗣勋等击破之。存信还，谮存孝无心击贼，疑与之有私约。存孝闻之，自以有功于克用，而信任顾不及存信，愤怨，且惧及祸，乃潜结王镕及硃全忠，上表以三州自归于朝廷，乞赐旌节及会诸道兵讨李克用；诏以存孝为邢、洺、磁节度使，不许会兵。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "c7c4930f-abcf-517f-8a46-382094c1e3b8", "subject_id": "d25efb4e-74a3-5bab-b1e4-a79cee0716c3", "source_id": "0d7e3338-8a8